    rn->max[0] = k_sp_max(p, a, leaf, INT64_MAX);
    rn->child[0] = a;
    rn->key[1] = k_sp_key(p, b, leaf);
    rn->max[1] = k_sp_max(p, b, leaf, INT64_MAX);
    rn->child[1] = b;
    K_SPHEAD(p)->root = r;
    K_SPHEAD(p)->height++;
