    rn->max[0] = k_spc_max(p, a, leaf, INT64_MAX);
    rn->child[0] = a;
    rn->key[1] = k_spc_key(p, b, leaf);
    rn->max[1] = k_spc_max(p, b, leaf, INT64_MAX);
    rn->child[1] = b;
    K_SPCHEAD(p)->root = r;
    K_SPCHEAD(p)->height++;
