        k_spleaf *r;
        nn = k_spc_newnode(p);
        if (nn == p->node[p->h]) k_spc_corrupt(p);
        r = K_SPLEAF(p, nn);
        r->n = lf->n - half;
        memcpy(r->idx, lf->idx + half, (size_t)r->n * 8);
        memcpy(r->cnt, lf->cnt + half, (size_t)r->n * 8);
        lf->n = half;
